// Section A Student - In-place Singly Linked List Reversal
Node* reverseList(Node* head) {
    if (head == nullptr || head->next == nullptr) {
        return head;
    }
    Node* prev = nullptr;
    Node* curr = head;
    Node* next = nullptr;

    while (curr != nullptr) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

// Section A Student
Node* reverseList(Node* head) {
    // Taught in Sec A lecture week 4: In-place helper recursion
    if (head == nullptr || head->next == nullptr) return head;
    Node* rest = reverseList(head->next);
    head->next->next = head;
    head->next = nullptr;
    return rest;
}

