// Section B Student - Full iterative reversal
Node* reverseList(Node* head) {
    if (head == NULL) return NULL;
    if (head->next == NULL) return head;

    Node* prev = NULL;
    Node* curr = head;
    Node* nextPtr = NULL;

    while (curr != NULL) {
        nextPtr = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextPtr;
    }
    return prev;
}

