// Section C Student
Node* reverseList(Node* head) {
    std::vector<int> vals;
    Node* temp = head;
    while(temp != NULL) {
        vals.push_back(temp->data);
        temp = temp->next;
    }
    temp = head;
    for(int i = vals.size()-1; i >= 0; i--) {
        temp->data = vals[i];
        temp = temp->next;
    }
    return head;
}

// Section C Student - Iterative method
Node* reverseList(Node* head) {
    Node* prev = NULL;
    Node* curr = head;
    while (curr) {
        Node* n = curr->next;
        curr->next = prev;
        prev = curr;
        curr = n;
    }
    return prev;
}
